INSERT INTO public.reviews (id, legacy_id, name, area, rating, text, service, approved)
VALUES ('ea2ee265-39bb-4490-8bb8-400ed00d8beb', NULL, 'عمر العكبري', 'الديس', 5, 'تجربتي مع هوم سنتر كانت أكثر من رائعة! المنتجات جميلة وجودتها ممتازة والتوصيل سريع والخدمة جدًا مميزة فعلًا مكان يستحق التجربة', 'معرض هوم سنتر (Home Centre)', TRUE)
