VALUES ('0170953d-dd06-4b13-8285-91caeb25e3f8', NULL, 'تجربة المتصفح', 'الديس', 5, 'تجربة رائعة مع المنصة', 'معرض أرض حمير للأثاث والمطابخ', FALSE)
