INSERT INTO public.reviews (id, legacy_id, name, area, rating, text, service, approved)
VALUES ('bff385ff-10ed-4d76-943f-3143992ff818', 'r3', 'خالد العمودي', 'فوة', 4, 'استفدت من مصمم الذكاء الاصطناعي في ترتيب مجلسي، ثم نفّذت التصميم مع ورشة باجابر. تجربة مريحة.', 'مصمم الذكاء الاصطناعي', TRUE)
