INSERT INTO public.reviews (id, legacy_id, name, area, rating, text, service, approved)
VALUES ('6ad2118e-9ed0-494b-87fa-819b3582b02c', 'r1', 'أحمد بامطرف', 'الديس', 5, 'تعاملت مع معرض أرض حمير على مطبخ متكامل، والنتيجة فاقت التوقعات. القياسات دقيقة والتركيب نظيف.', 'معرض أرض حمير للأثاث والمطابخ', TRUE)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.reviews (id, legacy_id, name, area, rating, text, service, approved)
VALUES ('e4d15f83-072b-4b52-b799-2429d6b1a245', NULL, 'رهف صقر', 'المكلا', 5, 'تجربة جميلة جدًا الأثاث جودته ممتازة والتفاصيل أجمل من المتوقع والتعامل راقٍ والتوصيل كان سريع جدًا شكرًا لكم على الخدمة الرائعة أكيد مش آخر تعامل ❤️', 'معرض أرض حمير للأثاث والمطابخ', TRUE)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.reviews (id, legacy_id, name, area, rating, text, service, approved)
VALUES ('37139073-41c5-4c92-afdd-481595f3680c', 'r4', 'سالم بن هلابي', 'باعبود', 5, 'المجلس الأرضي بتطريز حضرمي من مفروشات بن هلابي أضاف لبيتنا طابعاً أصيلاً. شكراً للفريق.', 'مفروشات بن هلابي', TRUE)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.reviews (id, legacy_id, name, area, rating, text, service, approved)
VALUES ('d5a776c1-c75f-4702-bb2c-40a07a61b081', 'r2', 'فاطمة بن سلمان', 'الشرج', 5, 'طقم الكنب من باصهيل وصل بوقت قياسي، والقماش فعلاً مقاوم للبقع كما وعدوا. خدمة راقية.', 'مفروشات باصهيل', TRUE)
