INSERT INTO public.reviews (id, legacy_id, name, area, rating, text, service, approved)
VALUES ('f4d044df-b851-443f-98ab-948bed641183', 'r5', 'نور باحسين', 'الأربعين', 5, 'م. ريم ساعدتني في تنسيق ألوان غرفة النوم، والنتيجة هادئة ومريحة جداً. أنصح بها.', 'م. ريم الكثيري', TRUE)
