-- الأسئلة الشائعة (6 سؤال)
INSERT INTO public.faqs (id, legacy_id, question, answer, sort_order)
VALUES ('521820f2-9826-44d3-bee1-fd12f0a6c3be', 'f1', 'كيف أطلب من معرض في المكلا؟', 'تصفح صفحة المعارض واختر المعرض المناسب، ثم اضغط «تصفح منتجات المعرض» لاستعراض قطعه، أو «محادثة المعرض» للتواصل المباشر. يمكنك أيضاً إضافة القطعة إلى السلة وإتمام الطلب، وسيتواصل معك فريق المعرض لتأكيد التفاصيل وموعد التسليم.', 1)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, legacy_id, question, answer, sort_order)
VALUES ('43a87a85-19ca-493b-b1e8-a99b3b5b36d0', 'f2', 'كيف يعمل مصمم الذكاء الاصطناعي؟', 'اختر نوع المساحة والميزانية والطابع الذي تحبه، وسيقترح عليك المصمم تشكيلة من قطع المعارض المحلية المناسبة لمساحتك وميزانيتك، مع إمكانية تعديل الاختيارات وإرسالها كطلب استشارة لمصمم بشري.', 2)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, legacy_id, question, answer, sort_order)
VALUES ('e806edac-934b-4d19-b093-2b95e3a74e89', 'f3', 'كيف أطلب تفصيلاً خاصاً من النجارين؟', 'من صفحة «المصممون والنجارون» اختر الورشة أو النجار المناسب واضغط «طلب تفصيل خاص»، ثم أدخل المقاسات والخامة المطلوبة ورقم التواصل. يصلك عرض سعر ومدة تنفيذ خلال ٤٨ ساعة عمل.', 3)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, legacy_id, question, answer, sort_order)
VALUES ('95436919-8d2e-42b7-ac65-ae728cc7b698', 'f4', 'ما طرق الدفع والتوصيل داخل المكلا وحضرموت؟', 'الدفع نقداً عند التسليم أو تحويل بنكي محلي. التوصيل داخل المكلا مجاني للطلبات فوق ٣٠٠٬٠٠٠ ر.ي، ويتم التوصيل إلى مدن حضرموت الأخرى (الشحر، سيئون، تريم) برسوم تحدد حسب المسافة وحجم القطعة.', 4)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, legacy_id, question, answer, sort_order)
VALUES ('77ff9b9a-5c51-473a-a2f4-62e8b4df1ac4', 'f5', 'ما سياسة الضمان على الأثاث؟', 'جميع القطع المفصّلة تحصل على ضمان سنتين على الهيكل والخشب، وسنة على المفصلات والإكسسوارات. الأثاث الجاهز يخضع لضمان المصنّع، ويشمل الضمان عيوب التصنيع ولا يشمل سوء الاستخدام أو الرطوبة.', 5)
ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, legacy_id, question, answer, sort_order)
VALUES ('93772a95-c27c-449b-ac9d-9a98a1701758', 'f6', 'هل يمكنني معاينة القطعة قبل الشراء؟', 'نعم، جميع المعارض المعروضة على المنصة لها عنوان حقيقي في المكلا ويمكن زيارتها. ننصح بالمعاينة للقطع الكبيرة مثل المطابخ وغرف النوم قبل تأكيد الطلب.', 6)
ON CONFLICT (id) DO NOTHING;

